/**
 * Process-wide notification bus for source-file changes.
 *
 * The change-detection pipeline calls {@link notifySourceFileChange} whenever a
 * watched source file is added/changed/removed. Consumers that care about those
 * events — most notably the review addon, which uses them to mark a cached
 * review as stale — subscribe via {@link subscribeToSourceFileChanges}.
 *
 * This is deliberately a tiny in-memory fan-out rather than a channel: the
 * producer (detector) and the consumers (presets) both live in the long-lived
 * dev-server process, so a shared module-level registry is the simplest thing
 * that works. A dev-server restart wipes it, which is fine.
 */
export type SourceFileChangeListener = (event: FileChangeEvent) => void;

const listeners = new Set<SourceFileChangeListener>();

/**
 * Register a listener for source-file changes. Returns an unsubscribe function
 * that detaches the listener; calling it more than once is a no-op.
 */
export function subscribeToSourceFileChanges(listener: SourceFileChangeListener): () => void {
  listeners.add(listener);
  return () => {
    listeners.delete(listener);
  };
}

/**
 * Deliver a change event to every registered listener.
 *
 * Iterates a snapshot so a listener that (un)subscribes during dispatch cannot
 * mutate the set mid-iteration. A throwing listener is isolated: its error is
 * swallowed so it neither aborts the remaining listeners nor propagates back to
 * the change detector that reported the event.
 */
export function notifySourceFileChange(event: FileChangeEvent): void {
  for (const listener of [...listeners]) {
    try {
      listener(event);
    } catch {
      // A misbehaving subscriber must not break change detection or starve the
      // other subscribers; there is nothing actionable to do with the error.
    }
  }
}

/**
 * Test-only: drop every registered listener so no further events are delivered.
 */
export function internal_resetSourceFileChangeListeners(): void {
  listeners.clear();
}
